["Pile_KeyHW22"]="Die Welt der Spiegelgläser",
["ENCHANTMENT_PLOT_TWIST"]="Wendung der Handlung",
["SetUi_DIRECTOR_Brief"]="Triff den Gegner mit Magie. Du wirst sehen, was passiert.",
["SetUi_DIRECTOR_Title"]="Regisseur",
["HELM_BP_S4_SCRIPTWRITER"]="Licht, Kamera, Action!",
["ARMOR_BP_S4_SCRIPTWRITER"]="Vierte Wand",
["WEAPON_BP_S4_SCRIPTWRITER"]="Leg dich nicht mit dem Regisseur an!",
